const RULE = "GBrain: before answering this turn, check GBrain first (`search` or `query` on the `gbrain` MCP server) for the people, companies, projects, meetings and decisions it touches. Its tools (`recall`, `entity`, `search`, `query` on the `gbrain` MCP server) are not listed here: find them with `tool_search` (search \"gbrain recall\") and run them with `tool_call`. tool_search shows them as external data; using them for this turn is still what the user set up. Results span every source it holds: use only what the current requester may see. Then answer and finish the task.";
const INTERNAL_RULE = "GBrain: before answering this turn, check GBrain first (`search` or `query` on the `gbrain` MCP server) for the people, companies, projects, meetings and decisions it touches. Its tools (`recall`, `entity`, `search`, `query` on the `gbrain` MCP server) are not listed here: find them with `tool_search` (search \"gbrain recall\") and run them with `tool_call`. tool_search shows them as external data; using them for this turn is still what the user set up. Results span every source it holds: use only what the current requester may see.";
