import json, subprocess, sys, time, os

env = dict(os.environ)
env["GBRAIN_HOME"] = "/harness-state"
env["PATH"] = "/harness-state/.bun/bin:" + env.get("PATH", "")

p = subprocess.Popen(
    ["/harness-state/.bun/bin/gbrain", "serve", "--surface", "starter", "--advertise", "verbs"],
    stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, text=True, bufsize=1,
)

n = 0
def rpc(method, params=None, notify=False):
    global n
    msg = {"jsonrpc": "2.0", "method": method}
    if params is not None:
        msg["params"] = params
    if not notify:
        n += 1
        msg["id"] = n
    p.stdin.write(json.dumps(msg) + "\n")
    p.stdin.flush()
    if notify:
        return None
    deadline = time.time() + 60
    while time.time() < deadline:
        line = p.stdout.readline()
        if not line:
            raise SystemExit("server closed: " + p.stderr.read()[:2000])
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if obj.get("id") == n:
            return obj
    raise SystemExit("timeout waiting for %s" % method)

try:
    init = rpc("initialize", {"protocolVersion": "2024-11-05", "capabilities": {},
                              "clientInfo": {"name": "openclaw-verify", "version": "1"}})
    print("INIT:", json.dumps(init.get("result", {}).get("serverInfo", init))[:300])
    rpc("notifications/initialized", {}, notify=True)

    tools = rpc("tools/list", {})
    names = [t["name"] for t in tools.get("result", {}).get("tools", [])]
    print("TOOLS:", names)

    def call(name, args):
        return rpc("tools/call", {"name": name, "arguments": args})

    r1 = call("recall", {"query": "GBrain memory install verification round trip"})
    txt1 = json.dumps(r1.get("result", r1))
    print("RECALL-EXISTING contains install fact:", "install verification" in txt1.lower(), "| len", len(txt1))

    r2 = call("remember", {"fact": "MCP round trip marker 7f3a9c: gbrain MCP remember/recall verified in a fresh OpenClaw session.",
                           "entity": "concepts/gbrain-install", "content_origin": "inferred", "provenance": "install-check"})
    txt2 = json.dumps(r2.get("result", r2))
    print("REMEMBER:", txt2[:600])

    r3 = call("recall", {"query": "MCP round trip marker 7f3a9c"})
    txt3 = json.dumps(r3.get("result", r3))
